// ===== Google Analytics 4 und Search Console (SLT) =====
// Anmeldung ueber ein Dienstkonto (JWT-Bearer-Flow). Das Dienstkonto gehoert
// SLT (dasselbe, das sie in Adverity nutzen), der Schluessel liegt als JSON in
// template_credentials. Kein Nutzerkonto, keine Zustimmung, kein Ablauf.
//
// Entscheidungen, die bewusst HIER im Code stehen und nicht in der
// Werkzeugbeschreibung: Zeitraeume in normaler Sprache, deutsche Metrik- und
// Dimensionsnamen, Voreinstellungen, Filter, Formatierung. Das Modell soll
// nichts raten muessen, was sich hier entscheiden laesst.

const input = { ...($input.first().json || {}) };
// Leere Werte zaehlen als nicht gesetzt: n8n veroeffentlicht jedes deklarierte
// Feld als Pflichtfeld, der Aufrufer fuellt fehlende deshalb mit "" auf.
for (const _k of Object.keys(input)) { if (input[_k] === '' || input[_k] === null) delete input[_k]; }

const action = String(input.action || '').trim();
const caller = String(input.caller || '').trim();

const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const PG = {
  apikey: SUPABASE_KEY,
  Authorization: 'Bearer ' + SUPABASE_KEY,
  'Content-Type': 'application/json',
};

const SCOPES = [
  'https://www.googleapis.com/auth/analytics.readonly',
  'https://www.googleapis.com/auth/webmasters.readonly',
];
const GSC_VERZUG_TAGE = 3; // Search Console liefert die letzten Tage unvollstaendig

function fehler(text) {
  return [{ json: { error: text } }];
}
function ergebnis(text) {
  return [{ json: { result: text } }];
}

// ---------- Zeitrechnung (Europe/Vienna, ohne Bibliothek) ----------

function heuteWien() {
  const f = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/Vienna', year: 'numeric', month: '2-digit', day: '2-digit',
  });
  const t = {};
  for (const p of f.formatToParts(new Date())) if (p.type !== 'literal') t[p.type] = p.value;
  return t.year + '-' + t.month + '-' + t.day;
}
function tagePlus(iso, tage) {
  const [j, m, t] = iso.split('-').map(Number);
  const d = new Date(Date.UTC(j, m - 1, t));
  d.setUTCDate(d.getUTCDate() + tage);
  return d.toISOString().slice(0, 10);
}
function monatsEnde(jahr, monat) {
  return new Date(Date.UTC(jahr, monat, 0)).toISOString().slice(0, 10);
}
function wochentag(iso) {
  const [j, m, t] = iso.split('-').map(Number);
  const wt = new Date(Date.UTC(j, m - 1, t)).getUTCDay(); // 0 = Sonntag
  return wt === 0 ? 7 : wt; // 1 = Montag
}

const MONATE = {
  januar: 1, jaenner: 1, january: 1, februar: 2, february: 2, maerz: 3, marz: 3, march: 3,
  april: 4, mai: 5, may: 5, juni: 6, june: 6, juli: 7, july: 7, august: 8,
  september: 9, oktober: 10, october: 10, november: 11, dezember: 12, december: 12,
};

function umlauteWeg(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
    .replace(/é|è/g, 'e');
}

// Gibt { start, end, text } oder { fehler }.
function zeitraumParsen(roh, vorgabeTage, bisTag) {
  const heute = heuteWien();
  const ende_vorgabe = bisTag || heute;
  const text = umlauteWeg(roh).trim();

  if (!text) {
    const start = tagePlus(ende_vorgabe, -(vorgabeTage - 1));
    return { start, end: ende_vorgabe, text: 'letzte ' + vorgabeTage + ' Tage (' + start + ' bis ' + ende_vorgabe + ')' };
  }

  // Ein Datum muss es wirklich geben: der 31.02. ging sonst an Google und kam
  // als 400 zurueck, was niemand versteht.
  const echtesDatum = (iso) => {
    const [j, m, t] = iso.split('-').map(Number);
    if (!j || m < 1 || m > 12 || t < 1 || t > 31) return false;
    const d = new Date(Date.UTC(j, m - 1, t));
    return d.getUTCFullYear() === j && d.getUTCMonth() === m - 1 && d.getUTCDate() === t;
  };
  const spanne = (a, b) => {
    if (!echtesDatum(a)) return { fehler: 'Das Datum "' + a + '" gibt es nicht.' };
    if (!echtesDatum(b)) return { fehler: 'Das Datum "' + b + '" gibt es nicht.' };
    if (a > b) return { fehler: 'Der Zeitraum beginnt nach seinem Ende (' + a + ' bis ' + b + '). Bitte in der richtigen Reihenfolge nennen.' };
    return { start: a, end: b, text: a + ' bis ' + b };
  };

  // Zwei ausdrueckliche Daten: 2026-09-01 bis 2026-09-30 oder 01.09.2026-30.09.2026
  const isoPaar = text.match(/(\d{4}-\d{2}-\d{2})\s*(?:bis|-|\.\.|to)\s*(\d{4}-\d{2}-\d{2})/);
  if (isoPaar) return spanne(isoPaar[1], isoPaar[2]);
  const dePaar = text.match(/(\d{1,2})\.(\d{1,2})\.(\d{4})\s*(?:bis|-|to)\s*(\d{1,2})\.(\d{1,2})\.(\d{4})/);
  if (dePaar) {
    const a = dePaar[3] + '-' + String(dePaar[2]).padStart(2, '0') + '-' + String(dePaar[1]).padStart(2, '0');
    const b = dePaar[6] + '-' + String(dePaar[5]).padStart(2, '0') + '-' + String(dePaar[4]).padStart(2, '0');
    return spanne(a, b);
  }
  // Ein einzelner Tag
  const einTag = text.match(/^(\d{4}-\d{2}-\d{2})$/);
  if (einTag) return spanne(einTag[1], einTag[1]);
  const einTagDe = text.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
  if (einTagDe) {
    const a = einTagDe[3] + '-' + String(einTagDe[2]).padStart(2, '0') + '-' + String(einTagDe[1]).padStart(2, '0');
    return spanne(a, a);
  }

  if (/^(heute|today)$/.test(text)) return { start: heute, end: heute, text: 'heute (' + heute + ')' };
  if (/^(gestern|yesterday)$/.test(text)) {
    const g = tagePlus(heute, -1);
    return { start: g, end: g, text: 'gestern (' + g + ')' };
  }
  if (/^vorgestern$/.test(text)) {
    const g = tagePlus(heute, -2);
    return { start: g, end: g, text: 'vorgestern (' + g + ')' };
  }

  // letzte 7 Tage, letzten 30 Tagen, 14 Tage
  const nTage = text.match(/(?:letzten?|vergangenen?|past|last)?\s*(\d{1,3})\s*(?:tage|tagen|days?)/);
  if (nTage) {
    const n = Math.max(1, Math.min(540, parseInt(nTage[1], 10)));
    const start = tagePlus(ende_vorgabe, -(n - 1));
    return { start, end: ende_vorgabe, text: 'letzte ' + n + ' Tage (' + start + ' bis ' + ende_vorgabe + ')' };
  }

  if (/(diese|aktuelle)\s*woche/.test(text)) {
    const start = tagePlus(heute, -(wochentag(heute) - 1));
    return { start, end: ende_vorgabe, text: 'diese Woche (' + start + ' bis ' + ende_vorgabe + ')' };
  }
  if (/(letzte|vorige|vergangene)\s*woche/.test(text)) {
    const montag = tagePlus(heute, -(wochentag(heute) - 1));
    const start = tagePlus(montag, -7);
    return { start, end: tagePlus(montag, -1), text: 'letzte Woche (' + start + ' bis ' + tagePlus(montag, -1) + ')' };
  }
  if (/(dieser|aktueller|laufender)\s*monat/.test(text)) {
    const start = heute.slice(0, 8) + '01';
    return { start, end: ende_vorgabe, text: 'dieser Monat (' + start + ' bis ' + ende_vorgabe + ')' };
  }
  if (/(letzter|voriger|vergangener)\s*monat/.test(text)) {
    const [j, m] = heute.split('-').map(Number);
    const jahr = m === 1 ? j - 1 : j;
    const monat = m === 1 ? 12 : m - 1;
    const start = jahr + '-' + String(monat).padStart(2, '0') + '-01';
    return { start, end: monatsEnde(jahr, monat), text: 'letzter Monat (' + start + ' bis ' + monatsEnde(jahr, monat) + ')' };
  }
  if (/(dieses|laufendes|aktuelles)\s*jahr/.test(text)) {
    const start = heute.slice(0, 4) + '-01-01';
    return { start, end: ende_vorgabe, text: 'dieses Jahr (' + start + ' bis ' + ende_vorgabe + ')' };
  }
  if (/(letztes|voriges|vergangenes)\s*jahr/.test(text)) {
    const j = Number(heute.slice(0, 4)) - 1;
    return { start: j + '-01-01', end: j + '-12-31', text: 'Jahr ' + j };
  }

  // Monatsname, mit oder ohne Jahr: "september", "september 2025"
  const monatName = text.match(/^([a-z]+)\s*(\d{4})?$/);
  if (monatName && MONATE[monatName[1]]) {
    const monat = MONATE[monatName[1]];
    const [jHeute, mHeute] = heute.split('-').map(Number);
    const jahr = monatName[2] ? Number(monatName[2]) : (monat > mHeute ? jHeute - 1 : jHeute);
    const start = jahr + '-' + String(monat).padStart(2, '0') + '-01';
    let end = monatsEnde(jahr, monat);
    if (end > ende_vorgabe) end = ende_vorgabe;
    return { start, end, text: monatName[1] + ' ' + jahr + ' (' + start + ' bis ' + end + ')' };
  }

  return { fehler: 'Zeitraum "' + roh + '" verstehe ich nicht. Moeglich sind: heute, gestern, "letzte 7 Tage", "diese Woche", "letzter Monat", "September", "September 2025", "dieses Jahr", oder zwei Daten wie "2026-09-01 bis 2026-09-30".' };
}

// ---------- Namen: deutsch und englisch auf API-Namen ----------

const GA4_METRIKEN = {
  sitzungen: 'sessions', sessions: 'sessions', besuche: 'sessions',
  nutzer: 'activeUsers', nutzerinnen: 'activeUsers', user: 'activeUsers', users: 'activeUsers',
  'aktive nutzer': 'activeUsers', activeusers: 'activeUsers',
  'gesamtnutzer': 'totalUsers', totalusers: 'totalUsers', 'alle nutzer': 'totalUsers',
  'neue nutzer': 'newUsers', newusers: 'newUsers', neukunden: 'newUsers',
  seitenaufrufe: 'screenPageViews', aufrufe: 'screenPageViews', pageviews: 'screenPageViews',
  screenpageviews: 'screenPageViews', seitenansichten: 'screenPageViews',
  'aufrufe je sitzung': 'screenPageViewsPerSession', 'seiten je sitzung': 'screenPageViewsPerSession',
  sitzungsdauer: 'averageSessionDuration', 'durchschnittliche sitzungsdauer': 'averageSessionDuration',
  verweildauer: 'userEngagementDuration', interaktionsdauer: 'userEngagementDuration',
  interaktionsrate: 'engagementRate', engagementrate: 'engagementRate',
  absprungrate: 'bounceRate', bouncerate: 'bounceRate',
  ereignisse: 'eventCount', events: 'eventCount', eventcount: 'eventCount',
  // conversions gibt es seit dem 06.05.2024 nicht mehr, der Nachfolger heisst
  // keyEvents. Alte Namen zeigen deshalb auf den neuen.
  conversions: 'keyEvents', konversionen: 'keyEvents', abschluesse: 'keyEvents',
  'wichtige ereignisse': 'keyEvents', keyevents: 'keyEvents',
  umsatz: 'totalRevenue', totalrevenue: 'totalRevenue', erloes: 'totalRevenue',
  sitzungen_je_nutzer: 'sessionsPerUser', 'sitzungen je nutzer': 'sessionsPerUser',
  'engagierte sitzungen': 'engagedSessions', engagedsessions: 'engagedSessions',
};

const GA4_DIMENSIONEN = {
  seite: 'pagePath', seitenpfad: 'pagePath', pagepath: 'pagePath', url: 'pagePath',
  seitentitel: 'pageTitle', titel: 'pageTitle', pagetitle: 'pageTitle',
  landingpage: 'landingPage', einstiegsseite: 'landingPage', landingpagepluszero: 'landingPage',
  quelle: 'sessionSource', sessionsource: 'sessionSource',
  medium: 'sessionMedium', sessionmedium: 'sessionMedium',
  'quelle/medium': 'sessionSourceMedium', quellemedium: 'sessionSourceMedium',
  sessionsourcemedium: 'sessionSourceMedium', herkunft: 'sessionSourceMedium',
  kanal: 'sessionDefaultChannelGroup', kanalgruppe: 'sessionDefaultChannelGroup',
  sessiondefaultchannelgroup: 'sessionDefaultChannelGroup',
  kampagne: 'sessionCampaignName', sessioncampaignname: 'sessionCampaignName',
  land: 'country', country: 'country', laender: 'country',
  stadt: 'city', city: 'city', ort: 'city',
  region: 'region',
  sprache: 'language', language: 'language',
  geraet: 'deviceCategory', geraetekategorie: 'deviceCategory', devicecategory: 'deviceCategory',
  browser: 'browser', betriebssystem: 'operatingSystem', operatingsystem: 'operatingSystem',
  datum: 'date', date: 'date', tag: 'date',
  woche: 'week', monat: 'yearMonth', yearmonth: 'yearMonth', jahr: 'year',
  stunde: 'hour', wochentag: 'dayOfWeekName',
  ereignis: 'eventName', eventname: 'eventName', ereignisname: 'eventName',
  suchbegriff: 'searchTerm', searchterm: 'searchTerm',
};

// GA4 liefert Laender und Staedte in englischer Schreibweise. Ein Filter
// "land = Oesterreich" traf deshalb nie etwas, und das Werkzeug meldete
// "keine Daten", als waere im September niemand aus Oesterreich gekommen.
const GA4_LAENDER = {
  oesterreich: 'Austria', osterreich: 'Austria', austria: 'Austria', at: 'Austria',
  deutschland: 'Germany', germany: 'Germany', de: 'Germany',
  schweiz: 'Switzerland', switzerland: 'Switzerland', ch: 'Switzerland',
  italien: 'Italy', italy: 'Italy', niederlande: 'Netherlands', netherlands: 'Netherlands',
  frankreich: 'France', france: 'France', tschechien: 'Czechia', czechia: 'Czechia',
  ungarn: 'Hungary', hungary: 'Hungary', polen: 'Poland', poland: 'Poland',
  slowenien: 'Slovenia', slovenia: 'Slovenia', belgien: 'Belgium', belgium: 'Belgium',
  daenemark: 'Denmark', denmark: 'Denmark', spanien: 'Spain', spain: 'Spain',
  grossbritannien: 'United Kingdom', uk: 'United Kingdom', england: 'United Kingdom',
  usa: 'United States', us: 'United States', amerika: 'United States',
  schweden: 'Sweden', sweden: 'Sweden', norwegen: 'Norway', norway: 'Norway',
};
const GA4_STAEDTE = {
  wien: 'Vienna', vienna: 'Vienna', muenchen: 'Munich', munchen: 'Munich', munich: 'Munich',
  koeln: 'Cologne', koln: 'Cologne', cologne: 'Cologne', nuernberg: 'Nuremberg', nurnberg: 'Nuremberg',
  zuerich: 'Zurich', zurich: 'Zurich', prag: 'Prague', prague: 'Prague',
  mailand: 'Milan', milan: 'Milan', rom: 'Rome', rome: 'Rome', bruessel: 'Brussels',
  warschau: 'Warsaw', kopenhagen: 'Copenhagen', moskau: 'Moscow',
};
const GA4_GERAETE = { handy: 'mobile', mobil: 'mobile', smartphone: 'mobile', rechner: 'desktop', computer: 'desktop', pc: 'desktop', laptop: 'desktop', tablett: 'tablet' };

function ga4FilterWert(dimension, wert) {
  const k = umlauteWeg(wert);
  if (dimension === 'country') return GA4_LAENDER[k] || wert;
  if (dimension === 'city') return GA4_STAEDTE[k] || wert;
  // GA4 schreibt die Geraeteklassen klein.
  if (dimension === 'deviceCategory') return GA4_GERAETE[k] || k;
  return wert;
}

// Echtzeit erlaubt nur diese Dimensionen (und nur die Metriken activeUsers,
// eventCount, keyEvents, screenPageViews).
const GA4_ECHTZEIT_DIMENSIONEN = {
  land: 'country', country: 'country',
  stadt: 'city', city: 'city',
  geraet: 'deviceCategory', geraetekategorie: 'deviceCategory', devicecategory: 'deviceCategory',
  ereignis: 'eventName', eventname: 'eventName',
  seite: 'unifiedScreenName', bildschirm: 'unifiedScreenName', unifiedscreenname: 'unifiedScreenName',
  plattform: 'platform', platform: 'platform',
  minuten: 'minutesAgo', minutesago: 'minutesAgo',
};

const GSC_DIMENSIONEN = {
  suchbegriff: 'query', suchbegriffe: 'query', query: 'query', keyword: 'query', begriff: 'query',
  seite: 'page', page: 'page', url: 'page',
  land: 'country', country: 'country',
  geraet: 'device', device: 'device',
  datum: 'date', date: 'date', tag: 'date',
  darstellung: 'searchAppearance', searchappearance: 'searchAppearance',
};

function nameAufloesen(roh, tabelle, art) {
  const key = umlauteWeg(roh).replace(/\s+/g, ' ').trim();
  if (tabelle[key]) return { name: tabelle[key] };
  const ohneLeer = key.replace(/\s/g, '');
  if (tabelle[ohneLeer]) return { name: tabelle[ohneLeer] };
  // Schon ein echter API-Name? (camelCase, kommt in der Tabelle als Wert vor)
  const werte = Object.values(tabelle);
  const treffer = werte.find((w) => w.toLowerCase() === key.replace(/\s/g, ''));
  if (treffer) return { name: treffer };
  const vorschlaege = [...new Set(werte)].filter((w) => umlauteWeg(w).includes(ohneLeer) || ohneLeer.length > 3 && umlauteWeg(w).startsWith(ohneLeer.slice(0, 4)));
  return {
    fehler: art + ' "' + roh + '" kenne ich nicht.'
      + (vorschlaege.length ? ' Gemeint vielleicht: ' + vorschlaege.slice(0, 5).join(', ') + '.' : '')
      + ' Bekannte Begriffe: ' + [...new Set(Object.keys(tabelle))].slice(0, 14).join(', ')
      + '. Mit ga4_fields findest du alle gueltigen Namen.',
  };
}

function listeAufloesen(roh, tabelle, art, grenze) {
  const teile = String(roh || '').split(/[,;]+/).map((s) => s.trim()).filter(Boolean);
  const namen = [];
  for (const t of teile) {
    const r = nameAufloesen(t, tabelle, art);
    if (r.fehler) return { fehler: r.fehler };
    if (!namen.includes(r.name)) namen.push(r.name);
    if (grenze && namen.length > grenze) return { fehler: 'Hoechstens ' + grenze + ' ' + art + ' je Abfrage.' };
  }
  return { namen };
}

// ---------- Filter: "land = Oesterreich", "seite enthaelt /winter" ----------

// Reihenfolge und Wortgrenzen sind hier wichtig und waren beide einmal falsch:
// "ereignis = view_item" wurde am "is" in "ereignis" zerschnitten, und
// "suchbegriff = wie wird das wetter" am "wie" IM WERT. Deshalb: Symbole
// zuerst, Wortformen nur mit Leerzeichen drumherum, und kein "wie" oder "like".
const OPERATOREN = [
  { muster: /\s*!=\s*/, art: 'EXACT', negiert: true },
  { muster: /\s*==?\s*/, art: 'EXACT', negiert: false },
  { muster: /\s+(?:enthaelt nicht|enthalt nicht|nicht enthaelt|not contains)\s+/i, art: 'CONTAINS', negiert: true },
  { muster: /\s+(?:enthaelt|enthalt|contains)\s+/i, art: 'CONTAINS', negiert: false },
  { muster: /\s+(?:beginnt mit|startet mit|begins with|starts with)\s+/i, art: 'BEGINS_WITH', negiert: false },
  { muster: /\s+(?:endet mit|ends with)\s+/i, art: 'ENDS_WITH', negiert: false },
  { muster: /\s+(?:ist nicht|nicht)\s+/i, art: 'EXACT', negiert: true },
  { muster: /\s+(?:ist|is)\s+/i, art: 'EXACT', negiert: false },
];

function filterParsen(roh, tabelle, art) {
  const text = String(roh || '').trim();
  if (!text) return { leer: true };
  // Alle moeglichen Trennstellen sammeln und die nehmen, deren linke Seite
  // wirklich ein Feldname ist. Wer nur das erste Muster nimmt, zerschneidet
  // "ereignis = view_item" am "is" in "ereignis" und
  // "seite enthaelt /a=b" am Gleichheitszeichen im Wert.
  const kandidaten = [];
  for (const op of OPERATOREN) {
    const m = text.match(op.muster);
    if (!m) continue;
    kandidaten.push({ op, i: text.indexOf(m[0]), len: m[0].length });
  }
  kandidaten.sort((a, b) => a.i - b.i || b.len - a.len);
  for (const k of kandidaten) {
    const links = text.slice(0, k.i).trim();
    const rechts = text.slice(k.i + k.len).trim().replace(/^["']|["']$/g, '');
    if (!links || !rechts) continue;
    const dim = nameAufloesen(links, tabelle, art);
    if (dim.fehler) continue;
    return { dimension: dim.name, wert: rechts, art: k.op.art, negiert: k.op.negiert };
  }
  return { fehler: 'Filter "' + roh + '" verstehe ich nicht. Muster: "land = Oesterreich", "seite enthaelt /winter", "quelle beginnt mit google", "land ist nicht Deutschland". Links vom Operator muss ein bekannter Feldname stehen.' };
}

// ---------- Zugangsdaten und Token ----------

async function zugangLesen() {
  let reihen;
  try {
    reihen = await helpers.httpRequest({
      method: 'GET',
      url: SUPABASE_URL + '/rest/v1/template_credentials?template_id=eq.google-web&select=cred_key,cred_value',
      headers: PG,
      json: true,
    });
  } catch (e) {
    return { fehler: 'Die Zugangsdaten sind nicht lesbar: ' + (e.message || 'unbekannter Fehler') };
  }
  const z = {};
  for (const r of reihen || []) z[r.cred_key] = r.cred_value;
  if (!z.service_account_json) {
    return { fehler: 'Der Google-Zugang ist noch nicht eingerichtet. Es fehlt der Dienstkonto-Schluessel (service_account_json). Freddy hat die Freigabe bei SLT angefragt; ich melde mich, sobald Analytics und Search Console offen sind.' };
  }
  let sa;
  try {
    sa = typeof z.service_account_json === 'string' ? JSON.parse(z.service_account_json) : z.service_account_json;
  } catch (e) {
    return { fehler: 'Der Dienstkonto-Schluessel ist kein gueltiges JSON.' };
  }
  if (!sa.client_email || !sa.private_key) {
    return { fehler: 'Im Dienstkonto-Schluessel fehlen client_email oder private_key.' };
  }
  return {
    sa,
    ga4: String(z.ga4_property_id || '').replace(/[^0-9]/g, ''),
    gsc: String(z.gsc_site_url || '').trim(),
  };
}

function base64url(bytes) {
  let b64;
  if (typeof Buffer !== 'undefined') {
    b64 = Buffer.from(bytes).toString('base64');
  } else {
    let t = '';
    const arr = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
    for (const b of arr) t += String.fromCharCode(b);
    b64 = btoa(t);
  }
  return b64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
function textBytes(t) {
  return new TextEncoder().encode(t);
}
function pemBytes(pem) {
  const roh = String(pem).replace(/-----[^-]+-----/g, '').replace(/\s+/g, '');
  if (typeof Buffer !== 'undefined') return Buffer.from(roh, 'base64');
  const bin = atob(roh);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

// RS256 ohne das crypto-Modul.
//
// Gemessen am 11.10.2026 auf der SLT-Instanz (n8n 2.34.5): im Code-Knoten gibt
// es weder das globale crypto noch require('crypto') ("Module 'crypto' is
// disallowed"). Vorhanden sind Buffer, btoa, TextEncoder und BigInt. Ein
// Dienstkonto-Token braucht aber eine RSA-Signatur, also wird sie hier
// gerechnet: SHA-256 von Hand, Polsterung nach RFC 8017 (RSASSA-PKCS1-v1_5),
// Potenzierung mit BigInt ueber den chinesischen Restsatz.
//
// Das ist kein Vertrauensbeweis, sondern eine Rechnung, und sie ist pruefbar:
// tests/google-web.test.js vergleicht das Ergebnis byteweise mit dem von
// node-crypto, fuer jede Nachrichtenlaenge von 0 bis 200. Stimmt ein Bit
// nicht, faellt der Test um.

// ---- SHA-256 ----
const SHA_K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

function sha256(bytes) {
  const h = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const laenge = bytes.length;
  const bitLaenge = laenge * 8;
  // Polstern: 0x80, Nullen, 64 Bit Laenge. Die Polsterung muss die KLEINSTE
  // sein, die passt: bei einer Laenge von genau 55 Bytes (55 + 1 + 8 = 64)
  // reicht ein Block. Ein Block zu viel liefert einen anderen Hash, und genau
  // das hat der byteweise Vergleich mit node-crypto gefunden.
  const voll = new Uint8Array((((laenge + 8) >> 6) + 1) << 6);
  voll.set(bytes);
  voll[laenge] = 0x80;
  // Laenge als 64-Bit big endian (die oberen 32 Bit bleiben 0, wir signieren
  // nie mehr als 512 MB)
  voll[voll.length - 4] = (bitLaenge >>> 24) & 0xff;
  voll[voll.length - 3] = (bitLaenge >>> 16) & 0xff;
  voll[voll.length - 2] = (bitLaenge >>> 8) & 0xff;
  voll[voll.length - 1] = bitLaenge & 0xff;

  const w = new Array(64);
  for (let i = 0; i < voll.length; i += 64) {
    for (let t = 0; t < 16; t++) {
      w[t] = ((voll[i + t * 4] << 24) | (voll[i + t * 4 + 1] << 16) | (voll[i + t * 4 + 2] << 8) | voll[i + t * 4 + 3]) >>> 0;
    }
    for (let t = 16; t < 64; t++) {
      const x = w[t - 15];
      const y = w[t - 2];
      const s0 = (((x >>> 7) | (x << 25)) ^ ((x >>> 18) | (x << 14)) ^ (x >>> 3)) >>> 0;
      const s1 = (((y >>> 17) | (y << 15)) ^ ((y >>> 19) | (y << 13)) ^ (y >>> 10)) >>> 0;
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, hh] = h;
    for (let t = 0; t < 64; t++) {
      const S1 = (((e >>> 6) | (e << 26)) ^ ((e >>> 11) | (e << 21)) ^ ((e >>> 25) | (e << 7))) >>> 0;
      const ch = ((e & f) ^ (~e & g)) >>> 0;
      const t1 = (hh + S1 + ch + SHA_K[t] + w[t]) >>> 0;
      const S0 = (((a >>> 2) | (a << 30)) ^ ((a >>> 13) | (a << 19)) ^ ((a >>> 22) | (a << 10))) >>> 0;
      const maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      const t2 = (S0 + maj) >>> 0;
      hh = g; g = f; f = e;
      e = (d + t1) >>> 0;
      d = c; c = b; b = a;
      a = (t1 + t2) >>> 0;
    }
    h[0] = (h[0] + a) >>> 0; h[1] = (h[1] + b) >>> 0; h[2] = (h[2] + c) >>> 0; h[3] = (h[3] + d) >>> 0;
    h[4] = (h[4] + e) >>> 0; h[5] = (h[5] + f) >>> 0; h[6] = (h[6] + g) >>> 0; h[7] = (h[7] + hh) >>> 0;
  }
  const aus = new Uint8Array(32);
  for (let i = 0; i < 8; i++) {
    aus[i * 4] = (h[i] >>> 24) & 0xff;
    aus[i * 4 + 1] = (h[i] >>> 16) & 0xff;
    aus[i * 4 + 2] = (h[i] >>> 8) & 0xff;
    aus[i * 4 + 3] = h[i] & 0xff;
  }
  return aus;
}

// ---- DER lesen, so viel wie fuer PKCS#8 noetig ----
function derTeil(b, pos) {
  const tag = b[pos];
  let i = pos + 1;
  let len = b[i++];
  if (len & 0x80) {
    const n = len & 0x7f;
    len = 0;
    for (let k = 0; k < n; k++) len = len * 256 + b[i++];
  }
  return { tag, inhalt: i, len, ende: i + len };
}
function derZahl(b, pos) {
  const t = derTeil(b, pos);
  if (t.tag !== 0x02) throw new Error('INTEGER erwartet, Tag ' + t.tag);
  let i = t.inhalt;
  let hex = '';
  for (; i < t.ende; i++) hex += t.inhalt === i && b[i] === 0 ? '' : b[i].toString(16).padStart(2, '0');
  return { wert: BigInt('0x' + (hex || '0')), ende: t.ende };
}

// Gibt die Felder des RSA-Schluessels aus einem PKCS#8-DER.
function rsaSchluessel(der) {
  const aussen = derTeil(der, 0);
  if (aussen.tag !== 0x30) throw new Error('PKCS8: aeussere SEQUENCE fehlt');
  let p = aussen.inhalt;
  const version = derTeil(der, p); p = version.ende;          // INTEGER 0
  const alg = derTeil(der, p); p = alg.ende;                   // SEQUENCE AlgorithmIdentifier
  const okt = derTeil(der, p);                                 // OCTET STRING
  if (okt.tag !== 0x04) throw new Error('PKCS8: OCTET STRING fehlt');
  const innen = derTeil(der, okt.inhalt);
  if (innen.tag !== 0x30) throw new Error('RSAPrivateKey: SEQUENCE fehlt');
  let q = innen.inhalt;
  const felder = [];
  for (let k = 0; k < 9 && q < innen.ende; k++) {
    const z = derZahl(der, q);
    felder.push(z.wert);
    q = z.ende;
  }
  if (felder.length < 9) throw new Error('RSAPrivateKey: nur ' + felder.length + ' Felder, 9 erwartet');
  return { n: felder[1], e: felder[2], d: felder[3], p: felder[4], q: felder[5], dp: felder[6], dq: felder[7], qinv: felder[8] };
}

// ---- Potenzieren ----
function modpow(basis, exp, mod) {
  let ergebnis = 1n;
  let b = basis % mod;
  let e = exp;
  while (e > 0n) {
    if (e & 1n) ergebnis = (ergebnis * b) % mod;
    b = (b * b) % mod;
    e >>= 1n;
  }
  return ergebnis;
}

const DIGESTINFO_SHA256 = [0x30, 0x31, 0x30, 0x0d, 0x06, 0x09, 0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x02, 0x01, 0x05, 0x00, 0x04, 0x20];

function hexVon(bytes) {
  let s = '';
  for (const b of bytes) s += b.toString(16).padStart(2, '0');
  return s;
}
function bytesVonBigInt(x, laenge) {
  let hex = x.toString(16);
  if (hex.length % 2) hex = '0' + hex;
  const roh = new Uint8Array(hex.length / 2);
  for (let i = 0; i < roh.length; i++) roh[i] = parseInt(hex.substr(i * 2, 2), 16);
  if (roh.length === laenge) return roh;
  const aus = new Uint8Array(laenge);
  aus.set(roh, laenge - roh.length);
  return aus;
}

// Signiert bytes (Uint8Array) mit einem PKCS#8-DER-Schluessel, RSASSA-PKCS1-v1_5
// mit SHA-256. Ergebnis: Uint8Array mit der Laenge des Modulus.
function rs256(der, bytes) {
  const s = rsaSchluessel(der);
  const k = (s.n.toString(16).length + 1) >> 1;          // Bytelaenge des Modulus
  const hash = sha256(bytes);
  const t = DIGESTINFO_SHA256.concat(Array.from(hash));  // DigestInfo
  if (k < t.length + 11) throw new Error('Schluessel zu kurz');
  // EM = 0x00 || 0x01 || 0xff... || 0x00 || T
  const em = new Uint8Array(k);
  em[0] = 0x00;
  em[1] = 0x01;
  const psLaenge = k - t.length - 3;
  for (let i = 0; i < psLaenge; i++) em[2 + i] = 0xff;
  em[2 + psLaenge] = 0x00;
  em.set(t, 3 + psLaenge);
  const m = BigInt('0x' + hexVon(em));
  // Chinesischer Restsatz: viermal schneller als die Potenz mit d.
  const m1 = modpow(m % s.p, s.dp, s.p);
  const m2 = modpow(m % s.q, s.dq, s.q);
  let diff = (m1 - m2) % s.p;
  if (diff < 0n) diff += s.p;
  const h = (s.qinv * diff) % s.p;
  const sig = m2 + h * s.q;
  return bytesVonBigInt(sig, k);
}

function jwtSignieren(sa, scopes) {
  const jetzt = Math.floor(Date.now() / 1000);
  const kopf = base64url(textBytes(JSON.stringify({ alg: 'RS256', typ: 'JWT' })));
  // exp darf hoechstens eine Stunde nach iat liegen, sonst weist Google den
  // JWT mit invalid_grant ab.
  const satz = base64url(textBytes(JSON.stringify({
    iss: sa.client_email,
    scope: scopes.join(' '),
    aud: sa.token_uri || 'https://oauth2.googleapis.com/token',
    exp: jetzt + 3600,
    iat: jetzt,
  })));
  const sig = rs256(pemBytes(sa.private_key), textBytes(kopf + '.' + satz));
  return kopf + '.' + satz + '.' + base64url(sig);
}

// Kein Zwischenspeicher: die Tabelle project_memory gibt es auf dieser Instanz
// nicht (geprueft), und eine neue Tabelle nur fuer ein Stundentoken waere zu
// viel Apparat. Jeder Werkzeugaufruf signiert deshalb selbst (rund 30 ms) und
// holt ein frisches Token. Sollte das je ins Gewicht fallen, ist die
// naheliegende Stelle eine eigene Tabelle mit UNIQUE auf den Schluessel.
async function tokenHolen(sa) {
  let jwt;
  try {
    jwt = jwtSignieren(sa, SCOPES);
  } catch (e) {
    throw new Error('Der Dienstkonto-Schluessel liess sich nicht verwenden: ' + (e.message || 'unbekannt'));
  }
  let antwort;
  try {
    antwort = await helpers.httpRequest({
      method: 'POST',
      url: sa.token_uri || 'https://oauth2.googleapis.com/token',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: 'grant_type=urn%3Aietf%3Aparams%3Aoauth%3Agrant-type%3Ajwt-bearer&assertion=' + encodeURIComponent(jwt),
      json: true,
    });
  } catch (e) {
    const code = String((e.response && e.response.statusCode) || e.httpCode || '');
    // Googles Begruendung steckt je nach n8n-Fassung an verschiedenen Stellen.
    // Sie ist wichtig: invalid_grant heisst Uhr oder Schluessel, unauthorized_client
    // heisst fehlende Delegation, invalid_scope heisst falscher Scope.
    const koerper = (e.response && (e.response.body || e.response.data))
      || (e.cause && e.cause.response && (e.cause.response.body || e.cause.response.data))
      || e.description || e.error || {};
    const k = typeof koerper === 'string' ? { error: koerper } : koerper;
    const grund = (k && (k.error_description || (typeof k.error === 'string' ? k.error : (k.error && k.error.message)))) || '';
    if (code === '400' && /invalid_grant/i.test(JSON.stringify(grund))) {
      throw new Error('Google weist das Dienstkonto ab (invalid_grant). Meist stimmt die Uhr des Servers nicht oder der Schluessel wurde zurueckgezogen.');
    }
    // Die Ursache muss mit, auch wenn der Fehler nicht die erwartete Form hat:
    // live kam hier einmal nur "Google gibt kein Token aus." an, und damit war
    // nicht zu erkennen, woran es lag.
    const rohtext = grund || (e && e.message) || String(e);
    throw new Error('Google gibt kein Token aus' + (code ? ' (HTTP ' + code + ')' : '')
      + (rohtext ? ': ' + String(rohtext).slice(0, 300) : '') + '.');
  }
  if (!antwort || !antwort.access_token) throw new Error('Google hat kein Token geliefert.');
  return antwort.access_token;
}

// ---------- Google-Aufrufe ----------

async function google(token, method, url, body) {
  try {
    return await helpers.httpRequest({
      method,
      url,
      headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
      body: body || undefined,
      json: true,
    });
  } catch (e) {
    const code = String((e.response && e.response.statusCode) || e.httpCode || '');
    const roh = (e.response && e.response.body) || {};
    const meldung = (roh.error && (roh.error.message || roh.error.status)) || e.message || '';
    if (code === '403') {
      throw new Error('Google verweigert den Zugriff (403). Entweder ist das Dienstkonto in dieser Property nicht freigegeben, oder die passende API ist im Google-Cloud-Projekt nicht aktiviert. Meldung von Google: ' + meldung);
    }
    if (code === '404') throw new Error('Google findet diese Property nicht (404): ' + meldung);
    if (code === '429') throw new Error('Google bremst gerade (Kontingent erreicht, 429). Bitte in einigen Minuten nochmal.');
    if (code === '400') throw new Error('Google lehnt die Abfrage ab (400): ' + meldung);
    throw new Error('Google antwortet mit einem Fehler' + (code ? ' (HTTP ' + code + ')' : '') + ': ' + meldung);
  }
}

// ---------- Formatierung ----------

// Zahlen selbst formatieren statt ueber toLocaleString: die Trennzeichen
// haengen sonst an der ICU-Fassung des Servers (de-AT setzt dort ein schmales
// Leerzeichen statt des Punkts), und die Antwort soll ueberall gleich aussehen.
function dezimal(v, stellen) {
  const x = Number(v);
  if (!isFinite(x)) return String(v);
  const fest = Math.abs(x).toFixed(stellen);
  const teile = fest.split('.');
  const ganz = teile[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return (x < 0 ? '-' : '') + ganz + (teile[1] ? ',' + teile[1] : '');
}
function zahl(n) {
  const x = Number(n);
  if (!isFinite(x)) return String(n);
  return Number.isInteger(x) ? dezimal(x, 0) : dezimal(x, 2);
}
function kuerzen(s, n) {
  const t = String(s == null ? '' : s);
  return t.length > n ? t.slice(0, n - 1) + '…' : t;
}
function tabelle(kopf, zeilen, grenze) {
  const max = grenze || 4500;
  const aus = [kopf.join(' | ')];
  for (const z of zeilen) {
    const zeile = z.join(' | ');
    if (aus.join('\n').length + zeile.length > max) {
      aus.push('… (gekuerzt, ' + (zeilen.length - (aus.length - 1)) + ' weitere Zeilen)');
      break;
    }
    aus.push(zeile);
  }
  return aus.join('\n');
}
