async function ga4Bericht(token, property, opt) {
  const koerper = {
    dateRanges: [{ startDate: opt.start, endDate: opt.end }],
    metrics: opt.metriken.map((m) => ({ name: m })),
    dimensions: opt.dimensionen.map((d) => ({ name: d })),
    limit: String(opt.grenze || 10),
    keepEmptyRows: false,
  };
  if (opt.sortierung) {
    const metrisch = opt.metriken.includes(opt.sortierung);
    koerper.orderBys = [metrisch
      ? { metric: { metricName: opt.sortierung }, desc: !opt.aufsteigend }
      : { dimension: { dimensionName: opt.sortierung }, desc: !opt.aufsteigend }];
  }
  if (opt.filter && !opt.filter.leer) {
    const f = {
      filter: {
        fieldName: opt.filter.dimension,
        stringFilter: {
          matchType: opt.filter.art,
          value: ga4FilterWert(opt.filter.dimension, opt.filter.wert),
          caseSensitive: false,
        },
      },
    };
    koerper.dimensionFilter = opt.filter.negiert ? { notExpression: f } : f;
  }
  const antwort = await google(token, 'POST',
    'https://analyticsdata.googleapis.com/v1beta/properties/' + property + ':runReport', koerper);

  const dimKopf = (antwort.dimensionHeaders || []).map((h) => h.name);
  const metKopf = (antwort.metricHeaders || []).map((h) => h.name);
  const zeilen = (antwort.rows || []).map((r) => [
    ...(r.dimensionValues || []).map((v, i) => (dimKopf[i] === 'date' ? datumLesbar(v.value) : kuerzen(v.value, 70))),
    ...(r.metricValues || []).map((v, i) => (metKopf[i] === 'averageSessionDuration' ? dauer(v.value) : (metKopf[i] === 'engagementRate' || metKopf[i] === 'bounceRate') ? prozent(v.value) : zahl(v.value))),
  ]);
  // Google sagt in den Metadaten, wenn Zeilen fehlen. Das darf der Agent nicht
  // verschweigen, sonst nennt er stillschweigend unvollstaendige Zahlen.
  const md = antwort.metadata || {};
  const hinweise = [];
  if (md.dataLossFromOtherRow) hinweise.push('Google hat seltene Werte zu einer Sammelzeile (other) zusammengefasst, die Aufschluesselung ist also nicht vollstaendig.');
  if (md.subjectToThresholding) hinweise.push('Google laesst aus Datenschutzgruenden Zeilen mit wenigen Nutzern weg, deshalb kann die Summe kleiner sein als die Gesamtzahl.');
  if ((md.samplingMetadatas || []).length) hinweise.push('Die Zahlen beruhen auf einer Stichprobe, nicht auf allen Daten.');
  return {
    kopf: [...dimKopf.map(metrikName), ...metKopf.map(metrikName)],
    zeilen,
    gesamt: antwort.rowCount || zeilen.length,
    summen: (antwort.totals && antwort.totals[0] && antwort.totals[0].metricValues) || null,
    metKopf,
    hinweise,
  };
}
function datumLesbar(v) {
  const s = String(v);
  return /^\d{8}$/.test(s) ? s.slice(6, 8) + '.' + s.slice(4, 6) + '.' + s.slice(0, 4) : s;
}
function dauer(sekunden) {
  const s = Math.round(Number(sekunden) || 0);
  const m = Math.floor(s / 60);
  return m > 0 ? m + ' min ' + (s % 60) + ' s' : s + ' s';
}
function prozent(v) {
  return dezimal(Number(v) * 100, 1) + ' %';
}

