  niederlande: 'nld', netherlands: 'nld', nl: 'nld', nld: 'nld',
  frankreich: 'fra', france: 'fra', fr: 'fra', fra: 'fra',
  tschechien: 'cze', czechia: 'cze', cz: 'cze', cze: 'cze',
  ungarn: 'hun', hungary: 'hun', hu: 'hun', hun: 'hun',
  polen: 'pol', poland: 'pol', pl: 'pol', pol: 'pol',
  slowenien: 'svn', slovenia: 'svn', si: 'svn', svn: 'svn',
  grossbritannien: 'gbr', uk: 'gbr', gb: 'gbr', gbr: 'gbr', england: 'gbr',
  usa: 'usa', us: 'usa', amerika: 'usa',
  belgien: 'bel', bel: 'bel', daenemark: 'dnk', dnk: 'dnk', spanien: 'esp', esp: 'esp',
};
const GSC_GERAETE = {
  handy: 'MOBILE', mobil: 'MOBILE', mobile: 'MOBILE', smartphone: 'MOBILE',
  rechner: 'DESKTOP', desktop: 'DESKTOP', computer: 'DESKTOP', pc: 'DESKTOP', laptop: 'DESKTOP',
  tablet: 'TABLET', tablett: 'TABLET',
};

function gscFilterWert(dimension, wert) {
  const k = umlauteWeg(wert);
  if (dimension === 'country') return GSC_LAENDER[k] || k;
  if (dimension === 'device') return GSC_GERAETE[k] || String(wert).toUpperCase();
  return wert;
}

async function gscAbfrage(token, seite, opt) {
  const koerper = {
    startDate: opt.start,
    endDate: opt.end,
    dimensions: opt.dimensionen,
    rowLimit: Math.max(1, Math.min(25000, opt.grenze || 10)),
    // final heisst: nur abgeschlossene Daten. Google nennt keine feste
    // Wartezeit, deshalb lieber endgueltige Zahlen als frische, die sich
    // morgen noch aendern.
    dataState: 'final',
  };
  if (opt.suchart && opt.suchart !== 'web') koerper.type = opt.suchart;
  if (opt.filter && !opt.filter.leer) {
    // Die Search Console hat keinen Praefix-Operator. "beginnt mit" und
    // "endet mit" waren hier stumm zu equals geworden, also hat Google auf die
    // exakte URL gefiltert und nichts gefunden, waehrend die Kopfzeile weiter
    // BEGINS_WITH behauptete. Jetzt wird daraus ein Regex, und der tatsaechlich
    // gesendete Operator kommt mit zurueck.
    const wert = gscFilterWert(opt.filter.dimension, opt.filter.wert);
    const maskiert = String(wert).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    let operator;
    let ausdruck = wert;
    if (opt.filter.art === 'CONTAINS') {
      operator = opt.filter.negiert ? 'notContains' : 'contains';
    } else if (opt.filter.art === 'BEGINS_WITH') {
      operator = opt.filter.negiert ? 'excludingRegex' : 'includingRegex';
      ausdruck = '^' + maskiert;
    } else if (opt.filter.art === 'ENDS_WITH') {
      operator = opt.filter.negiert ? 'excludingRegex' : 'includingRegex';
      ausdruck = maskiert + '$';
    } else {
      operator = opt.filter.negiert ? 'notEquals' : 'equals';
    }
    opt.filter.gesendet = operator + ' ' + ausdruck;
    koerper.dimensionFilterGroups = [{
      groupType: 'and',
      filters: [{ dimension: opt.filter.dimension, operator, expression: ausdruck }],
    }];
  }
  const antwort = await google(token, 'POST',
    'https://www.googleapis.com/webmasters/v3/sites/' + encodeURIComponent(seite) + '/searchAnalytics/query', koerper);
  // Die Suchanalyse kennt keine Sortierung: sie liefert nach Klicks absteigend.
  // Bei einer Zeitreihe ist das unbrauchbar, also hier nach Datum ordnen.
  const datumSpalte = opt.dimensionen.indexOf('date');
  if (datumSpalte >= 0 && antwort.rows) {
    antwort.rows.sort((a, b) => String((a.keys || [])[datumSpalte]).localeCompare(String((b.keys || [])[datumSpalte])));
  }
  const zeilen = (antwort.rows || []).map((r) => [
    ...(r.keys || []).map((k, i) => (opt.dimensionen[i] === 'date' ? datumLesbar(String(k).replace(/-/g, '')) : kuerzen(k, 70))),
    zahl(r.clicks), zahl(r.impressions),
    prozent(r.ctr),
    dezimal(r.position, 1),
  ]);
  return { zeilen, kopf: [...opt.dimensionen, 'Klicks', 'Impressionen', 'CTR', 'Position'] };
}

// ---------- Ablauf ----------

if (action === 'selftest') {
  const z = await zugangLesen();
  const teile = [
    // Die Signatur rechnet dieser Code selbst (RS256 ohne crypto-Modul, das im
    // n8n-Knoten gesperrt ist). Hier wird nur geprueft, dass sie laeuft.
    'Signatur: ' + (() => {
      try {
        const t0 = Date.now();
        const laenge = z.fehler ? 0 : jwtSignieren(z.sa, SCOPES).length;
        return laenge ? 'eigene RS256-Rechnung ok, JWT ' + laenge + ' Zeichen in ' + (Date.now() - t0) + ' ms' : 'nicht geprueft, kein Schluessel';
      } catch (e) {
        return 'FEHLER ' + (e.message || e);
      }
    })(),
    'Buffer: ' + (typeof Buffer !== 'undefined' ? 'da' : 'fehlt'),
    'TextEncoder: ' + (typeof TextEncoder !== 'undefined' ? 'da' : 'FEHLT'),
    'Intl Europe/Vienna: ' + heuteWien(),
    'Zugangsdaten: ' + (z.fehler ? z.fehler : 'gelesen, GA4=' + (z.ga4 || 'fehlt') + ', GSC=' + (z.gsc || 'fehlt')),
  ];
  if (!z.fehler) {
    let t = null;
    try {
      t = await tokenHolen(z.sa);
      teile.push('Token: geholt, Laenge ' + String(t).length);
    } catch (e) {
      teile.push('Token: FEHLER ' + e.message);
    }
    if (t) {
      // Was sieht das Dienstkonto wirklich? Das beantwortet jede Frage nach
      // Freigaben ohne Rueckfrage beim Kunden.
      try {
        const seiten = await google(t, 'GET', 'https://www.googleapis.com/webmasters/v3/sites');
        const liste = ((seiten && seiten.siteEntry) || []).map((x) => x.siteUrl + ' [' + x.permissionLevel + ']');
        teile.push('Search-Console-Properties: ' + (liste.length ? liste.join(', ') : 'keine, das Dienstkonto ist nirgends eingetragen'));
      } catch (e) {
        teile.push('Search-Console-Properties: FEHLER ' + e.message);
      }
      try {
        const probe = await google(t, 'POST', 'https://analyticsdata.googleapis.com/v1beta/properties/' + z.ga4 + ':runReport',
          { dateRanges: [{ startDate: '7daysAgo', endDate: 'yesterday' }], metrics: [{ name: 'sessions' }], limit: '1' });
        const wert = (((probe.rows || [])[0] || {}).metricValues || [{}])[0].value;
        teile.push('GA4-Probe: ok, Sitzungen letzte 7 Tage = ' + (wert === undefined ? 'keine Daten' : wert));
      } catch (e) {
        teile.push('GA4-Probe: FEHLER ' + e.message);
      }
    }
  }
  return ergebnis(teile.join('\n'));
}

const z = await zugangLesen();
if (z.fehler) return fehler(z.fehler);

let token;
try {
  token = await tokenHolen(z.sa);
} catch (e) {
  return fehler(e.message);
}

// ---- GA4: freier Bericht ----
if (action === 'ga4_report' || action === 'ga4_quick') {
  const property = String(input.property_id || z.ga4 || '').replace(/[^0-9]/g, '');
  if (!property) return fehler('Es ist keine GA4-Property hinterlegt. Entweder property_id mitgeben oder ga4_property_id in den Zugangsdaten setzen.');

  let metriken, dimensionen, sortierung, aufsteigend, titel;
  if (action === 'ga4_quick') {
    const name = umlauteWeg(input.preset || 'ueberblick').replace(/[\s-]+/g, '_');
    const v = VOREINSTELLUNGEN[name];
    if (!v) return fehler('Voreinstellung "' + (input.preset || '') + '" gibt es nicht. Moeglich: ' + Object.keys(VOREINSTELLUNGEN).join(', ') + '.');
    metriken = v.metriken; dimensionen = v.dimensionen; sortierung = v.sortierung; aufsteigend = v.aufsteigend; titel = v.beschreibung;
  } else {
    const m = listeAufloesen(input.metrics || 'sitzungen, nutzer', GA4_METRIKEN, 'Metrik', 10);
    if (m.fehler) return fehler(m.fehler);
    const d = listeAufloesen(input.dimensions || '', GA4_DIMENSIONEN, 'Dimension', 5);
    if (d.fehler) return fehler(d.fehler);
    metriken = m.namen; dimensionen = d.namen;
    if (input.order_by) {
      // Getrennt aufloesen, damit klar ist, OB nach einer Metrik oder einer
      // Dimension sortiert wird. Vorher entschied das allein, ob der Name
      // zufaellig in metriken stand: eine Metrik, die nicht abgefragt wurde,
      // ging als Dimension an Google und brachte einen 400er.
      const alsMetrik = nameAufloesen(input.order_by, GA4_METRIKEN, 'Metrik');
      const alsDimension = nameAufloesen(input.order_by, GA4_DIMENSIONEN, 'Dimension');
      if (!alsMetrik.fehler) {
        sortierung = alsMetrik.name;
        // Nach etwas sortieren, das nicht in der Tabelle steht, kann Google
        // nicht. Dann die Metrik mit abfragen.
        if (!metriken.includes(sortierung)) metriken = metriken.concat([sortierung]);
      } else if (!alsDimension.fehler) {
        sortierung = alsDimension.name;
        if (!dimensionen.includes(sortierung)) {
          return fehler('Nach "' + input.order_by + '" kann ich nur sortieren, wenn diese Aufschluesselung auch abgefragt wird. Bitte ' + sortierung + ' zu den Dimensionen nehmen oder nach einer Metrik sortieren.');
        }
      } else {
        return fehler(alsMetrik.fehler);
      }
    } else {
      sortierung = dimensionen.includes('date') ? 'date' : metriken[0];
      aufsteigend = dimensionen.includes('date');
    }
    titel = 'Bericht';
  }

  const zr = zeitraumParsen(input.period, 28);
  if (zr.fehler) return fehler(zr.fehler);
  const f = filterParsen(input.filter, GA4_DIMENSIONEN, 'Dimension');
  if (f.fehler) return fehler(f.fehler);

  // Bei einer Zeitreihe muss die Zeilenzahl zum Zeitraum passen. Mit der
  // Vorgabe 10 und aufsteigender Datumssortierung kamen die zehn AELTESTEN
  // Tage des Zeitraums zurueck, und die Kopfzeile sagte trotzdem
  // "letzte 28 Tage": aus einem Monat wurde heimlich die erste Woche.
  const tageImZeitraum = Math.round((Date.parse(zr.end) - Date.parse(zr.start)) / 86400000) + 1;
  const grenze = Number(input.limit)
    ? Math.max(1, Math.min(250, Number(input.limit)))
    : (dimensionen.includes('date') ? Math.max(1, Math.min(250, tageImZeitraum))
      : (dimensionen.length ? 10 : 1));
  let r;
  try {
    r = await ga4Bericht(token, property, {
      start: zr.start, end: zr.end, metriken, dimensionen, sortierung, aufsteigend,
      grenze,
      filter: f,
    });
  } catch (e) {
    return fehler(e.message);
  }
  if (!r.zeilen.length) return ergebnis(titel + ' (' + zr.text + '): keine Daten. Der Zeitraum kann zu frueh liegen, oder der Filter trifft nichts.');

  const kopfzeile = 'GA4 ' + titel + ', ' + zr.text + (f.leer ? '' : ', Filter: ' + f.dimension + ' ' + f.art + ' ' + ga4FilterWert(f.dimension, f.wert));
  // Den Hinweis auf die letzten Tage nur geben, wenn der juengste Tag wirklich
  // in der Tabelle steht.
  const juengsterInTabelle = !dimensionen.includes('date') || r.zeilen.length >= tageImZeitraum;
  const frisch = zr.end >= tagePlus(heuteWien(), -1) && juengsterInTabelle;
  const fuss = (r.hinweise || []).concat(frisch ? ['Die letzten ein bis zwei Tage koennen sich noch aendern, Google verarbeitet sie noch.'] : []);
  const fusszeile = fuss.length ? '\n' + fuss.map((h) => 'Hinweis: ' + h).join('\n') : '';
  if (!dimensionen.length) {
    const werte = r.zeilen[0] || [];
    return ergebnis(kopfzeile + '\n' + r.kopf.map((k, i) => k + ': ' + werte[i]).join('\n') + fusszeile);
  }
  return ergebnis(kopfzeile + '\n' + tabelle(r.kopf, r.zeilen)
    + (r.gesamt > r.zeilen.length ? '\n(' + zahl(r.gesamt) + ' Zeilen insgesamt)' : '') + fusszeile);
}

// ---- GA4: Echtzeit ----
if (action === 'ga4_realtime') {
  const property = String(input.property_id || z.ga4 || '').replace(/[^0-9]/g, '');
  if (!property) return fehler('Es ist keine GA4-Property hinterlegt.');
  // Echtzeit kennt nur ein kleines Schema (Doku: realtime-api-schema). Eine
  // Dimension wie pagePath laesst Google hier mit 400 abblitzen, deshalb
  // pruefen wir vorher und sagen, was geht.
  const d = input.dimensions ? listeAufloesen(input.dimensions, GA4_ECHTZEIT_DIMENSIONEN, 'Echtzeit-Dimension', 2) : { namen: ['country'] };
  if (d.fehler) return fehler(d.fehler);
  let antwort;
  try {
    antwort = await google(token, 'POST',
      'https://analyticsdata.googleapis.com/v1beta/properties/' + property + ':runRealtimeReport',
      {
        metrics: [{ name: 'activeUsers' }],
        dimensions: d.namen.map((x) => ({ name: x })),
        limit: '20',
        // Die Gesamtzahl kommt von Google, nicht aus der Summe der Zeilen: bei
        // mehr als 20 Laendern waere die Summe zu klein, und niemand saehe es.
        metricAggregations: ['TOTAL'],
      });
  } catch (e) {
    return fehler(e.message);
  }
  const zeilen = (antwort.rows || []).map((r) => [
    ...(r.dimensionValues || []).map((v) => kuerzen(v.value, 50)),
    zahl((r.metricValues || [{}])[0].value),
  ]);
  if (!zeilen.length) return ergebnis('Gerade niemand auf der Seite (letzte 30 Minuten).');
  const gesamtWert = (((antwort.totals || [])[0] || {}).metricValues || [{}])[0].value;
  const summeZeilen = (antwort.rows || []).reduce((s, r) => s + Number(((r.metricValues || [{}])[0] || {}).value || 0), 0);
  const gesamt = gesamtWert === undefined ? summeZeilen : Number(gesamtWert);
  const mehr = (antwort.rowCount || zeilen.length) > zeilen.length || gesamt > summeZeilen;
  return ergebnis('GA4 Echtzeit, letzte 30 Minuten, ' + zahl(gesamt) + ' aktive Nutzer'
    + (mehr ? ' (die Tabelle zeigt die ersten ' + zeilen.length + ' Zeilen)' : '') + ':\n'
    + tabelle([...d.namen, 'aktive Nutzer'], zeilen, 1500));
}

// ---- GA4: gueltige Namen nachschlagen ----
if (action === 'ga4_fields') {
  const property = String(input.property_id || z.ga4 || '').replace(/[^0-9]/g, '');
  if (!property) return fehler('Es ist keine GA4-Property hinterlegt, deshalb kann ich die Feldliste nicht abfragen.');
  const suche = umlauteWeg(input.query || '');
  let antwort;
  try {
    antwort = await google(token, 'GET',
      'https://analyticsdata.googleapis.com/v1beta/properties/' + property + '/metadata');
  } catch (e) {
    return fehler(e.message);
  }
  const passt = (x) => !suche || umlauteWeg(x.apiName).includes(suche) || umlauteWeg(x.uiName || '').includes(suche);
  const met = (antwort.metrics || []).filter(passt).slice(0, 30).map((x) => x.apiName + ' (' + (x.uiName || '') + ')');
  const dim = (antwort.dimensions || []).filter(passt).slice(0, 30).map((x) => x.apiName + ' (' + (x.uiName || '') + ')');
  if (!met.length && !dim.length) return ergebnis('Zu "' + (input.query || '') + '" gibt es in dieser Property nichts.');
  return ergebnis('Metriken:\n' + (met.join('\n') || 'keine') + '\n\nDimensionen:\n' + (dim.join('\n') || 'keine'));
}

// ---- Search Console: Suchanalyse ----
if (action === 'gsc_search') {
  const seite = String(input.site_url || z.gsc || '').trim();
  if (!seite) return fehler('Es ist keine Search-Console-Property hinterlegt (gsc_site_url), zum Beispiel sc-domain:salzburgerland.com.');
  const d = listeAufloesen(input.dimensions || 'suchbegriff', GSC_DIMENSIONEN, 'Dimension', 3);
  if (d.fehler) return fehler(d.fehler);
  if (d.namen.includes('searchAppearance') && d.namen.length > 1) {
    return fehler('Die Darstellung in der Suche (searchAppearance) laesst Google nur allein abfragen, nicht zusammen mit anderen Aufschluesselungen. Bitte entweder nur darstellung, oder die anderen ohne sie.');
  }
  const bis = tagePlus(heuteWien(), -GSC_VERZUG_TAGE);
  const zr = zeitraumParsen(input.period, 28, bis);
  if (zr.fehler) return fehler(zr.fehler);
  // Einen ausdruecklich genannten Zeitraum kappen, statt eine leere Tabelle zu
  // liefern: wer nach heute oder gestern fragt, soll die Erklaerung bekommen.
  let gekappt = '';
  if (zr.start > bis) {
    return fehler('Fuer diesen Zeitraum hat Google noch keine endgueltigen Zahlen. Die Search Console gibt die letzten Tage erst mit einigen Tagen Verzug frei, abfragbar ist derzeit bis ' + bis + '.');
  }
  if (zr.end > bis) {
    zr.end = bis;
    gekappt = ' (bis ' + bis + ' gekappt, weiter ist noch nichts endgueltig)';
  }
  const f = filterParsen(input.filter, GSC_DIMENSIONEN, 'Dimension');
  if (f.fehler) return fehler(f.fehler);
  // Die Suchart ist eine feste Liste und steht bei Google in genauer
  // Schreibweise. Kleinschreiben allein machte aus googleNews ein ungueltiges
  // googlenews.
  const SUCHARTEN = {
    web: 'web', websuche: 'web', '': 'web',
    image: 'image', images: 'image', bild: 'image', bilder: 'image',
    video: 'video', videos: 'video',
    news: 'news', nachrichten: 'news',
    discover: 'discover',
    googlenews: 'googleNews', 'google news': 'googleNews', googlenachrichten: 'googleNews',
  };
  const suchartRoh = umlauteWeg(input.search_type || 'web');
  if (!SUCHARTEN[suchartRoh]) {
    return fehler('Die Suchart "' + input.search_type + '" kenne ich nicht. Moeglich sind: web, image, video, news, discover, googleNews.');
  }
  const suchart = { wert: SUCHARTEN[suchartRoh] };
  // Bei einer Zeitreihe muss die Zeilenzahl zum Zeitraum passen, sonst zeigt
  // die Antwort die zehn klickstaerksten Tage und sieht aus wie ein Verlauf.
  const tageImZeitraum = Math.round((Date.parse(zr.end) - Date.parse(zr.start)) / 86400000) + 1;
  const grenzeGsc = Number(input.limit)
    ? Math.max(1, Math.min(250, Number(input.limit)))
    : (d.namen.includes('date') ? Math.max(1, Math.min(400, tageImZeitraum)) : 10);
  let r;
  try {
    r = await gscAbfrage(token, seite, {
      start: zr.start, end: zr.end, dimensionen: d.namen, filter: f,
      grenze: grenzeGsc,
      suchart: suchart.wert,
    });
  } catch (e) {
    return fehler(e.message);
  }
  if (!r.zeilen.length) return ergebnis('Search Console, ' + zr.text + gekappt + ': keine Zeilen. Entweder gab es keine Einblendungen, oder der Filter trifft nichts.');
  const notizen = ['Google gibt die letzten Tage erst mit Verzug endgueltig frei, der Zeitraum endet deshalb am ' + zr.end + '.'];
  if (d.namen.includes('query')) {
    notizen.push('Suchanfragen, die nur wenige Menschen stellen, laesst Google aus Datenschutzgruenden weg. Die Summe der Zeilen ist deshalb kleiner als die Gesamtzahl der Klicks.');
  }
  if (r.zeilen.length >= grenzeGsc) {
    notizen.push('Es sind nur die ersten ' + grenzeGsc + ' Zeilen, nach Klicks absteigend. Die Search Console nennt keine Gesamtzahl.');
  }
  return ergebnis('Search Console (' + seite + '), ' + zr.text + gekappt
    // Den Filter so nennen, wie er wirklich an Google ging, nicht wie er
    // gemeint war.
    + (f.leer ? '' : ', Filter: ' + f.dimension + ' ' + (f.gesendet || (f.art + ' ' + f.wert)))
    + '\n' + notizen.map((x) => 'Hinweis: ' + x).join('\n') + '\n'
    + tabelle(r.kopf, r.zeilen));
}

// ---- Search Console: URL pruefen ----
if (action === 'gsc_inspect') {
  const seite = String(input.site_url || z.gsc || '').trim();
  const url = String(input.url || '').trim();
  if (!seite) return fehler('Es ist keine Search-Console-Property hinterlegt (gsc_site_url), ohne die kann Google die URL nicht zuordnen.');
  if (!url) return fehler('Welche URL soll ich pruefen? Bitte die vollstaendige Adresse mitgeben.');
  if (!/^https?:\/\//i.test(url)) return fehler('Die URL muss mit http:// oder https:// beginnen.');
  let antwort;
  try {
    antwort = await google(token, 'POST', 'https://searchconsole.googleapis.com/v1/urlInspection/index:inspect',
      { inspectionUrl: url, siteUrl: seite, languageCode: 'de' });
  } catch (e) {
    return fehler(e.message);
  }
  const r = (antwort && antwort.inspectionResult) || {};
  const i = r.indexStatusResult || {};
  const zeilen = [
    'URL: ' + url,
    'Im Index: ' + (i.coverageState || 'unbekannt'),
    'Zuletzt erfasst: ' + (i.lastCrawlTime ? datumLesbar(String(i.lastCrawlTime).slice(0, 10).replace(/-/g, '')) : 'nie'),
    'Von Google gewaehlte Adresse: ' + (i.googleCanonical || 'keine Angabe'),
    'Von der Seite angegeben: ' + (i.userCanonical || 'keine Angabe'),
    'Roboterregel: ' + (i.robotsTxtState || 'unbekannt'),
    'Indexierung erlaubt: ' + (i.indexingState || 'unbekannt'),
  ];
  if (r.mobileUsabilityResult && r.mobileUsabilityResult.verdict) zeilen.push('Mobil nutzbar: ' + r.mobileUsabilityResult.verdict);
  if (r.richResultsResult && r.richResultsResult.verdict) zeilen.push('Strukturierte Daten: ' + r.richResultsResult.verdict);
  if (r.inspectionResultLink) zeilen.push('In der Search Console ansehen: ' + r.inspectionResultLink);
  return ergebnis(zeilen.join('\n'));
}

return fehler('Unbekannte Aktion "' + action + '". Moeglich: ga4_report, ga4_quick, ga4_realtime, ga4_fields, gsc_search, gsc_inspect.');
